{"command": "python3 - <<'EOF'
import glob,json,re,collections
err=collections.Counter(); warnusers=collections.Counter(); db=[]; over=0; total_done=0; lat=collections.Counter()
for f in glob.glob('logs/*'):
    isjson=f.endswith('.jsonl')
    for ln,line in enumerate(open(f),1):
        line=line.rstrip('\n')
        if not line: continue
        if isjson:
            o=json.loads(line); ts=o['ts']; lvl=o['level']; svc=o['service']; msg=o['msg']
        else:
            m=re.match(r'^(\S+)\s+(\S+)\s+\[([^\]]+)\]\s+(.*)$',line)
            if not m: print('BAD',f,ln,line); continue
            ts,lvl,svc,msg=m.groups()
        if lvl=='ERROR': err[svc]+=1
        if lvl=='WARN' and svc=='auth':
            mm=re.search(r'login failed user=(\S+)',msg)
            if mm: warnusers[mm.group(1)]+=1
            else: print('WARN auth other',f,ln,line)
        if 'db timeout' in msg: db.append((ts,svc,lvl,msg,f,ln))
        if 'request done' in msg:
            total_done+=1
            mm=re.search(r'latency_ms=(\d+)',msg)
            if not mm: print('NOLAT',f,ln,line)
            else:
                l=int(mm.group(1)); lat[l]+=1
                if l>2000: over+=1
print('errors',dict(err))
print('warnusers',warnusers.most_common())
print('db count',len(db))
for x in sorted(db)[:10]: print(x)
print('total_done',total_done,'over',over)
print('lat min/max',min(lat),max(lat))
print('exact 2000',lat[2000],'2001',lat[2001])
EOF", "description": "Compute all incident metrics from both formats"}

